<?php
 namespace Pterodactyl\Console\Commands\Dezerx; use Illuminate\Console\Command; use Pterodactyl\Models\Dezerx\RustWipe; use Pterodactyl\Models\Dezerx\RustWipeRun; use Pterodactyl\Services\Dezerx\Rust\RustWipes; class RunRustWipes extends Command { protected $signature = 'dezerx:run-rust-wipes'; protected $description = 'Warns players, stops, wipes and restarts Rust servers whose wipe is due.'; public function handle(RustWipes $wipes): int { if (!RustWipeRun::query()->whereIn('status', RustWipeRun::ACTIVE)->exists() && !RustWipe::query()->where('enabled', true)->whereNotNull('next_run_at')->exists()) { return self::SUCCESS; } $now = time(); $armed = $wipes->arm($now); foreach ($wipes->active() as $run) { $before = $run->status; $wipes->advance($run, time()); if ($run->status !== $before) { $this->line("Wipe {$run->id} on server {$run->server_id}: {$before} -> {$run->status}"); } } if ($armed > 0) { $this->info("Armed {$armed} " . ($armed === 1 ? 'wipe.' : 'wipes.')); } return self::SUCCESS; } } 